@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if not n.begins_with("."):
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_walk(p, out)
			else:
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func _scan_logs(base: String, depth: int, out: Array) -> void:
	if depth > 3:
		return
	var d := DirAccess.open(base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if not n.begins_with("."):
			var p := base + "/" + n
			if d.current_is_dir():
					_scan_logs(p, depth + 1, out)
			elif n.ends_with(".log"):
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk("", files)
	var rep := {}
	rep["total_files"] = files.size()
	var imports := 0
	var stale: Array = []
	var missing: Array = []
	var sample: Array = []
	for f in files:
		if String(f).get_extension() == "import":
			imports += 1
			var txt: String = FileAccess.get_file_as_string("res://" + f)
			var arr := txt.split("source_file=\"")
			if arr.size() > 1:
				var sf: String = arr[1].get_slice("\"", 0)
				var expect: String = "res://" + String(f).substr(0, String(f).length() - 7)
				if not FileAccess.file_exists(sf):
					missing.append(f)
					if sample.size() < 50:
						sample.append("MISSING_SRC " + f + " -> " + sf)
				elif sf != expect:
					stale.append(f)
					if sample.size() < 50:
							sample.append("STALE_SRC " + f + " -> " + sf)
	rep["import_count"] = imports
	rep["stale_source_count"] = stale.size()
	rep["missing_source_count"] = missing.size()
	rep["samples"] = sample
	var logs: Array = []
	var appdata := OS.get_environment("APPDATA")
	var gd := DirAccess.open(appdata + "/Godot")
	if gd != null:
		_scan_logs(appdata + "/Godot", 0, logs)
	rep["log_files"] = logs
	if logs.size() > 0:
		var newest := ""
		var best := 0
		for l in logs:
			var mt := FileAccess.get_modified_time(String(l))
			if mt > best:
				best = mt
				newest = String(l)
		if newest != "":
			var txt2 := FileAccess.get_file_as_string(newest)
			var lines := txt2.split("\n")
			var joined := ""
			var start := maxi(0, lines.size() - 400)
			for i in range(start, lines.size()):
				joined += lines[i] + "\n"
			var lf := FileAccess.open("res://tools/gc_diag_log.txt", FileAccess.WRITE)
			if lf != null:
				lf.store_string("LOGFILE: " + newest + "\n" + joined)
			rep["newest_log"] = newest
	var out := FileAccess.open("res://tools/gc_diag_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "DIAG rc=0 files=" + str(files.size()) + " imports=" + str(imports) + " stale=" + str(stale.size()) + " missing=" + str(missing.size()) + " logs=" + str(logs.size())
